// Evolution ayarları: bot akışındaki değerlerle aynı olmalı
const EVOLUTION_URL = 'https://EVOLUTION-ADRESI.up.railway.app';
const EVOLUTION_INSTANCE = 'vetray';

const out = [];
for (const item of $input.all()) {
  const r = item.json;
  if (!r.conversation_id || !r.wa_number) continue;

  // Ardışık aynı roldeki mesajları birleştir, ilk mesaj müşteriden olsun
  const messages = [];
  for (const h of r.history ?? []) {
    if (!h.content) continue;
    const last = messages[messages.length - 1];
    if (last && last.role === h.role) last.content += '\n' + h.content;
    else messages.push({ role: h.role, content: h.content });
  }
  while (messages.length && messages[0].role !== 'user') messages.shift();
  if (!messages.length) continue;
  // Son mesaj bizden: modelden yeni bir takip mesajı istenir
  const task = r.kind === '24h'
    ? 'Müşteri yaklaşık bir gündür yanıt vermedi. Nazik, kısa bir ikinci hatırlatma yazın.'
    : 'Müşteri birkaç saattir yanıt vermedi. Nazik, kısa bir ilk takip mesajı yazın.';
  messages.push({ role: 'user', content: '[Sistem notu, müşteri yazmadı] ' + task });

  const system = [
    'Siz Vetray adına WhatsApp üzerinden müşterilere takip mesajı yazan asistansınız.',
    'Resmi ve kibar yazın, Türkçede "siz" dili kullanın. Müşteri İngilizce yazdıysa resmi ve kibar İngilizce kullanın. En fazla iki kısa cümle. Baskıcı olmayın, soru sorarak yardım teklif edin. Tire veya uzun tire karakteri kullanmayın. Emoji kullanmayın. Yalnızca mesaj metnini yazın, başka açıklama eklemeyin.',
    'Yalnızca konuşma geçmişindeki ve işletme bilgisindeki bilgilere dayanın; fiyat, tarih veya taahhüt uydurmayın.',
    r.system_prompt ? 'Konuşma tarzı:\n' + r.system_prompt : '',
    'İşletme bilgisi:\n' + (r.business_info || '(henüz girilmedi)'),
  ].filter(Boolean).join('\n\n');

  out.push({ json: {
    conversation_id: r.conversation_id,
    wa_number: r.wa_number,
    evolution_url: EVOLUTION_URL.replace(/\/$/, ''),
    evolution_instance: EVOLUTION_INSTANCE,
    body: {
      model: 'deepseek-v4.1-flash',
      max_tokens: 2000,
      messages: [{ role: 'system', content: system }, ...messages],
    },
  } });
}
return out;

const out = [];
const items = $input.all();
const prevAll = $('İstemi Hazırla').all();
for (let i = 0; i < items.length; i++) {
  const res = items[i].json;
  const prev = prevAll[i].json;
  const choice = (res.choices ?? [])[0];
  if (!choice || choice.finish_reason === 'content_filter') continue;
  const text = choice.message?.content;
  const reply = typeof text === 'string' ? text.replace(/[\u2013\u2014]/g, ',').trim() : '';
  if (reply) out.push({ json: { conversation_id: prev.conversation_id, wa_number: prev.wa_number, evolution_url: prev.evolution_url, evolution_instance: prev.evolution_instance, reply } });
}
return out;
